package com.makemytrip.makemytrip.services;
import com.makemytrip.makemytrip.models.Seat;import com.makemytrip.makemytrip.repositories.SeatRepository;import org.springframework.data.mongodb.core.MongoTemplate;import org.springframework.data.mongodb.core.FindAndModifyOptions;import org.springframework.data.mongodb.core.query.*;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.List;
@Service public class SeatService {private final SeatRepository seats;private final MongoTemplate mongo;public SeatService(SeatRepository r,MongoTemplate m){seats=r;mongo=m;}public List<Seat> list(String flightId){return seats.findByFlightId(flightId);}public Seat save(String flight,Seat seat){seat.setFlightId(flight);return seats.save(seat);}public Seat claim(String flight,String number,String booking){Query q=new Query(Criteria.where("flightId").is(flight).and("seatNumber").is(number).and("status").is(Seat.Status.AVAILABLE));return mongo.findAndModify(q,new Update().set("status",Seat.Status.BOOKED).set("bookingId",booking),FindAndModifyOptions.options().returnNew(true),Seat.class);}public boolean release(String flight,String number,String booking){Query q=new Query(Criteria.where("flightId").is(flight).and("seatNumber").is(number).and("status").is(Seat.Status.BOOKED).and("bookingId").is(booking));return mongo.updateFirst(q,new Update().set("status",Seat.Status.AVAILABLE).unset("bookingId"),Seat.class).getModifiedCount()==1;}}
